//! 🪢️ Bounded backing keeps the array cursor resident across its paid lifecycle.
use super::*;
use crate::{NativeProjectionBacking,SnapshotProjectionCursor};

/// 📦️ Owns one lazily seeded array cursor and its authenticated Source.
pub struct BoundedArrayProjection<T:RetainedClone,const N:usize>{backing:NativeProjectionBacking<ArrayProjection<T,N>>,source:Option<((u64,usize,usize,usize),OriginalWorkBindingIdentity)>,closing:bool}
impl<T:RetainedClone,const N:usize> BoundedArrayProjection<T,N>{
 /// 🌱️ Creates only an empty native descriptor.
 pub fn new()->Self{Self{backing:NativeProjectionBacking::new(ArrayProjection::seed_template()),source:None,closing:false}}
 fn capture_demand()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<Option<((u64,usize,usize,usize),OriginalWorkBindingIdentity)>>(),depth:1,..Default::default()}}
 fn child(&self)->Result<&ArrayProjection<T,N>,ValueError>{self.backing.get().ok_or_else(||invalid("array cursor backing is not initialized"))}
 fn child_mut(&mut self)->Result<&mut ArrayProjection<T,N>,ValueError>{self.backing.get_mut().ok_or_else(||invalid("array cursor backing is not initialized"))}
 fn check_source(&self,source:RetainedCloneRef<'_,[T;N]>)->Result<(),ValueError>{if self.source.is_some_and(|(identity,_)|identity!=source.reference_identity()){return Err(invalid("bounded array changed original Source"))}Ok(())}
 fn check_work(&self,effect:&RetainedAllocationEffect<'_>)->Result<(),ValueError>{if self.source.is_some_and(|(_,work)|!work.matches_effect(effect)){return Err(invalid("bounded array changed original Work"))}Ok(())}
 fn close_capture_demand(&self)->RetirementDemand{if self.source.is_some(){Self::capture_demand()}else{Default::default()}}
 fn proof(&self)->Result<Option<RetainedCursorRelease<ArrayProjection<T,N>>>,ValueError>{match self.backing.retained(){Some(cursor)=>{let proof=cursor.native_terminal_release().ok_or_else(||invalid("array cursor lacks native release"))?;if !proof.validates(cursor){return Err(invalid("array cursor release witness changed"))}Ok(Some(proof))},None=>Ok(None)}}
}
impl<T:RetainedClone,const N:usize> Default for BoundedArrayProjection<T,N>{fn default()->Self{Self::new()}}
impl<T:RetainedClone,const N:usize> SnapshotProjectionCursor<[T;N]> for BoundedArrayProjection<T,N>{
 fn demands(&self,source:RetainedCloneRef<'_,[T;N]>,body:usize,maximum:u64)->Result<RetirementDemand,ValueError>{if self.closing{return Err(invalid("bounded array is closing"))}self.check_source(source)?;if maximum==0{return Ok(Default::default())}if self.source.is_none(){return Ok(Self::capture_demand())}if !self.backing.initialized(){return self.backing.birth_demand()}self.child()?.demands(source,body,maximum)}
 fn advance_work_demand(&self,source:RetainedCloneRef<'_,[T;N]>,body:usize,maximum:u64)->Result<u64,ValueError>{self.demands(source,body,maximum)?;if maximum==0{return Ok(0)}if self.source.is_none(){return Ok(1)}if !self.backing.initialized(){return Ok(self.backing.birth_work_demand())}self.child()?.advance_work_demand(source,body,maximum)}
 fn advance_into<'r>(&mut self,source:RetainedCloneRef<'_,[T;N]>,body:usize,maximum:u64,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>{let demand=self.demands(source,body,maximum)?;let work=self.advance_work_demand(source,body,maximum)?;if work==0||effect.remaining_work_units()?<work||!retained_clone_grant_admits(effect.grant(),demand){return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}if effect.work_source_turn().is_none(){return Err(invalid("bounded array lacks original Source"))}self.check_work(effect)?;if self.source.is_none(){if !effect.performed(1)?{return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"bounded array Source capture exceeded Work").into())))}self.source=Some((source.reference_identity(),OriginalWorkBindingIdentity::from_effect(effect)));return Ok(reply.complete(Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()}))))}if !self.backing.initialized(){let mut result=None;drop(self.backing.birth_into(effect,OriginalEffectReply::borrow(&mut result)?)?);return crate::forward_original_value_reply(&mut result,reply.progress())}self.child_mut()?.advance_into(source,body,maximum,effect,reply)}
 fn recover_advance_into<'r>(&mut self,source:RetainedCloneRef<'_,[T;N]>,body:usize,maximum:u64,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>{self.check_source(source)?;self.check_work(effect)?;self.child_mut()?.recover_advance_into(source,body,maximum,effect,reply)}
 fn ready(&self)->bool{self.backing.get().is_some_and(ArrayProjection::ready)}
 fn take_demand(&self)->Result<RetirementDemand,ValueError>{self.child()?.take_demand()}
 fn take_work_demand(&self)->Result<u64,ValueError>{self.child()?.take_work_demand()}
 fn take_into<'r>(&mut self,output:&mut Option<Box<[T;N]>>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{self.check_work(effect)?;self.child_mut()?.take_into(output,effect,reply)}
 fn recover_take_into<'r>(&mut self,output:&mut Option<Box<[T;N]>>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{self.check_work(effect)?;self.child_mut()?.recover_take_into(output,effect,reply)}
 fn close_started(&self)->bool{self.closing}
 fn begin_close_demand(&self)->Result<RetirementDemand,ValueError>{Ok(if self.closing{Default::default()}else{RetirementDemand{copy_bytes:size_of::<bool>(),depth:1,..Default::default()}})}
 fn begin_close_work_demand(&self)->Result<u64,ValueError>{Ok(u64::from(!self.closing))}
 fn begin_close_into<'r>(&mut self,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>{self.check_work(effect)?;if self.closing{return Ok(reply.complete(Ok(RetainedCloneStep::Complete(Default::default()))))}let d=self.begin_close_demand()?;if effect.remaining_work_units()?<1||!retained_clone_grant_admits(effect.grant(),d){return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}if !effect.performed(1)?{return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"bounded array close start exceeded Work").into())))}self.closing=true;Ok(reply.complete(Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))))}
 fn recover_begin_close_into<'r>(&mut self,_:&mut RetainedAllocationEffect<'_>,_:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>{Err(invalid("native array close start cannot replay"))}
 fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid("bounded array close has not started"))}if let Some(cursor)=self.backing.get(){if !cursor.close_started(){return cursor.begin_close_demand()}if !cursor.terminal_is_empty(){return cursor.close_demands(body)}}if !self.backing.terminal_is_empty(){let proof=self.proof()?;return self.backing.release_demand(proof.as_ref())}Ok(self.close_capture_demand())}
 fn close_work_demand(&self,body:usize)->Result<u64,ValueError>{self.close_demands(body)?;if let Some(cursor)=self.backing.get(){if !cursor.close_started(){return cursor.begin_close_work_demand()}if !cursor.terminal_is_empty(){return cursor.close_work_demand(body)}}if !self.backing.terminal_is_empty(){return Ok(self.backing.release_work_demand())}Ok(u64::from(self.source.is_some()))}
 fn close_into<'r>(&mut self,body:usize,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>{self.check_work(effect)?;if let Some(cursor)=self.backing.get_mut(){if !cursor.close_started(){return cursor.begin_close_into(effect,reply.progress())}if !cursor.terminal_is_empty(){return cursor.close_into(body,effect,reply.progress())}}if !self.backing.terminal_is_empty(){let proof=self.proof()?;let mut result=None;drop(self.backing.release_into(proof,effect,OriginalEffectReply::borrow(&mut result)?)?);return crate::forward_original_value_reply(&mut result,reply.progress())}if self.source.is_none(){return Ok(reply.complete(Ok(RetainedCloneStep::Complete(Default::default()))))}let d=self.close_capture_demand();if effect.remaining_work_units()?<1||!retained_clone_grant_admits(effect.grant(),d){return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}if !effect.performed(1)?{return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"bounded array Source release exceeded Work").into())))}self.source=None;Ok(reply.complete(Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))))}
 fn recover_close_into<'r>(&mut self,body:usize,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>{self.check_work(effect)?;let child=self.child_mut()?;if !child.close_started(){child.recover_begin_close_into(effect,reply.progress())}else{child.recover_close_into(body,effect,reply.progress())}}
 fn requires_original_birth(&self)->bool{self.backing.get().is_some_and(|cursor|cursor.close_started()&&cursor.requires_original_birth())}
 fn close_original_birth_step(&mut self,original:&mut OriginalRetirementCloseLoan<'_>,grant:RetainedCloneGrant)->OriginalRetirementPoll{match self.backing.get_mut(){Some(cursor)=>cursor.close_original_birth_step(original,grant),None=>RetainedWorkPoll::Complete(crate::RetainedWorkOutcome{result:Err(invalid("bounded array has no original Birth").into()),work:0})}}
 fn requires_original_control(&self)->bool{self.backing.get().is_some_and(|cursor|cursor.close_started()&&cursor.requires_original_control())}
 fn close_original_into<'r>(&mut self,original:&mut OriginalRetirementCloseLoan<'_>,body:usize,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>{self.check_work(effect)?;self.child_mut()?.close_original_into(original,body,effect,reply.progress())}
 fn recover_close_original_into<'r>(&mut self,original:&mut OriginalRetirementCloseLoan<'_>,body:usize,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>{self.check_work(effect)?;self.child_mut()?.recover_close_original_into(original,body,effect,reply.progress())}
 fn terminal_is_empty(&self)->bool{self.closing&&self.source.is_none()&&self.backing.terminal_is_empty()}
 fn native_terminal_release(&self)->Option<RetainedCursorRelease<Self>>{if !self.terminal_is_empty(){return None}Some(unsafe{RetainedCursorRelease::native(|owner:&Self|owner.terminal_is_empty())})}
}
